namespace {
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
template<class T,class A>void shortBudgets(T&task,const kstation::FlashCredits&credits,unsigned&calls,uint64_t&checks,A&&advance){auto cost=task.nextClocks(credits);std::array<uint8_t,sizeof(T)>snapshot;std::memcpy(snapshot.data(),&task,sizeof(T));auto before=calls;for(unsigned budget=0;budget<cost;++budget){check(!advance(budget)&&calls==before&&!std::memcmp(snapshot.data(),&task,sizeof(T)),"Short budget mutated task/IO");++checks;}}
class Original final:public H8SEmulator{public:int readHistory()const{return lastread;}int writeHistory()const{return lastwrite;}int irqDepth()const{return indent;}void histories(int r,int w){lastread=r;lastwrite=w;}void irqDepth(int d){indent=d;}};
using C=kstation::Stage1Cpu;
struct Event{uint64_t clocks;unsigned pc,at;std::array<int32_t,8>regs;uint8_t flags,exr,value;bool write;};
template<class Cpu>class Bus final:public H8SDevice{public:Cpu&c;unsigned count=0,command=0,remaining=0,pageWrites=0,lcdReads=0,lcdBusy=0,lastReads=0,stallReads=0;bool dropLast=false;unsigned dropIndex=~0u;uint8_t lcdClearValue=0;uint32_t page=0,tick=0;std::array<Event,8>events{};explicit Bus(Cpu&p):c(p){}void record(unsigned at,uint8_t v,bool w){check(count<events.size(),"IO overflow");auto&e=events[count++];e={c.cycles,unsigned(c.getPC()),at,{},c.ccr,c.exr,v,w};for(unsigned j=0;j<8;++j)e.regs[j]=c.regs[j].er;}uint8_t read(unsigned at)override{uint8_t v=c.memory[at];if(at==0x600004)v=uint8_t(6|(c.memory[0x600000]&8?16:0));if(at>=0xfffd20&&at<=0xfffd23){if(at==0xfffd20)tick=uint32_t(c.cycles/1000);v=uint8_t(tick>>((0xfffd23-at)*8));}if(at==0xffffc7)v=lcdReads++<lcdBusy?0x80:lcdClearValue;if(pageWrites==256&&at==page+255&&lastReads++<stallReads)v^=1;record(at,v,false);return v;}
 void write(unsigned at,uint8_t v)override{record(at,v,true);if(at>=0x200000&&at<0x240000){auto offset=at-0x200000;if(command==3){if(!pageWrites)page=at;if((!dropLast||remaining!=1)&&pageWrites!=dropIndex)c.memory[at]=v;++pageWrites;if(!--remaining)command=0;return;}if(command==0&&offset==0x5555&&v==0xaa)command=1;else if(command==1&&offset==0x2aaa&&v==0x55)command=2;else if(command==2&&offset==0x5555&&v==0xa0){command=3;remaining=256;}else command=0;return;}c.memory[at]=v;}
};
struct Fixture {std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<C>b=std::make_unique<C>();Bus<Original>x{*a};Bus<C>y{*b};kstation::NativeForegroundClock native;uint64_t openChildren=0;uint64_t handlers=0,steps=0,io=0,programs=0,irqSteps=0,mutations=0;unsigned liveScenario=0;bool nested=false,mutate=false,injected=false;void byte(unsigned at,unsigned v){a->memory[at&0xffffff]=b->memory[at&0xffffff]=uint8_t(v);}void word(unsigned at,unsigned v){byte(at,v>>8);byte(at+1,v);}void wide(unsigned at,unsigned v){word(at,v>>16);word(at+2,v);}
 explicit Fixture(const std::vector<uint8_t>&rom){a->loadmem(rom.data(),rom.size(),0);b->loadmem(rom.data(),rom.size(),0);for(auto r:{std::pair{0x200000,0x40000},std::pair{0xfffd00,0x300},std::pair{0xba00,0x300},std::pair{0xce00,0x400},std::pair{0xcd00,0x100},std::pair{0xc580,0x30},std::pair{0x600000,16},std::pair{0x3fff80,0x100}}){a->memmap(&x,r.first,r.second);b->memmap(&y,r.first,r.second);}}
 void prepare(unsigned entry,unsigned flags,unsigned target=0x21fe00,unsigned sp=0xffff00){native.reset();for(unsigned j=0;j<8;++j)a->regs[j].er=b->regs[j].er=int32_t(0x9a6c0011+j*0x122334);a->pc=a->makepc(entry);b->pc=b->makepc(entry);a->setSP(sp);b->setSP(sp);wide(sp,0x3ae8);a->reg32(5)=b->reg32(5)=0xce1e;a->reg32(6)=b->reg32(6)=target;a->cycles=b->cycles=flags==255?~uint64_t(0)-5:100000;a->ccr=b->ccr=uint8_t(flags);a->exr=b->exr=0x5a;a->pending_irqs=b->pending_irqs=0;a->histories(0x200001,0xfffe6f);b->histories(0x200001,0xfffe6f);a->irqDepth(3);b->irqDepth(3);x.command=y.command=x.remaining=y.remaining=x.pageWrites=y.pageWrites=x.lcdReads=y.lcdReads=x.lcdBusy=y.lcdBusy=x.lastReads=y.lastReads=x.stallReads=y.stallReads=0;x.dropLast=y.dropLast=false;x.dropIndex=y.dropIndex=~0u;x.lcdClearValue=y.lcdClearValue=0;nested=mutate=injected=false;word(0xfffe32,0xfffe);for(unsigned j=0;j<256;++j){byte(0xce1e + j,j*73+19);byte(0x21fe00+j,j*73+19);byte(0x21ff00+j,j*13+7);}for(unsigned j=0;j<23;++j)byte(0xbb12+j,j*17+3);++handlers;}
 void equal(unsigned at){bool same=a->cycles==b->cycles&&a->getPC()==b->getPC()&&a->ccr==b->ccr&&a->exr==b->exr&&a->readHistory()==b->readHistory()&&a->writeHistory()==b->writeHistory()&&a->irqDepth()==b->irqDepth();for(unsigned j=0;j<8;++j)same&=a->regs[j].er==b->regs[j].er;if(!same){std::fprintf(stderr,"At%x PC%x/%x clocks%llu/%llu flags%x/%x R0%x/%x R1%x/%x R2%x/%x R5%x/%x R6%x/%x\n",at,a->getPC(),b->getPC(),a->cycles,b->cycles,a->ccr,b->ccr,a->reg32(0),b->reg32(0),a->reg32(1),b->reg32(1),a->reg32(2),b->reg32(2),a->reg32(5),b->reg32(5),a->reg32(6),b->reg32(6));throw std::runtime_error("Context differs");}check(x.count==y.count,"IO count differs");for(unsigned j=0;j<x.count;++j){auto&p=x.events[j];auto&q=y.events[j];if(!(p.clocks==q.clocks&&p.pc==q.pc&&p.at==q.at&&p.regs==q.regs&&p.flags==q.flags&&p.exr==q.exr&&p.value==q.value&&p.write==q.write)){std::fprintf(stderr,"IO At%x event%u at%x/%x value%x/%x flags%x/%x clocks%llu/%llu\n",at,j,p.at,q.at,p.value,q.value,p.flags,q.flags,p.clocks,q.clocks);throw std::runtime_error("IO context differs");}}io+=x.count;}
 void whole(bool allowOpen=false){bool opened=false;for(unsigned j=0;j<250000&&a->getPC()!=0x3ae8;++j){x.count=y.count=0;auto at=unsigned(a->getPC());if(!injected&&at==0xc40&&unsigned(a->reg32(0))%256==128&&(nested||mutate)){if(nested)a->pending_irqs=b->pending_irqs=uint64_t(1)<<38;if(mutate){byte(0xce1e + 128,0x17);++mutations;}injected=true;}if(mutate&&!injected){if(liveScenario==1&&at==0x1898){wide(0xfffe56,0x3456789a);injected=true;}else if(liveScenario==2&&at==0x18f2){byte(0xfffe6e,1);word(0xfffe7c,0x800);injected=true;}else if(liveScenario==3&&(at==0x185e||at==0x186a)){byte(0xfffe6f,0xa7);injected=true;}else if(liveScenario>=4&&at==0x1916){constexpr unsigned deltas[]={0u,0xfffu,0x1000u,0xfffff000u,0xfffff001u};wide(0xfffe6a,uint32_t(a->reg32(1))+deltas[liveScenario-4]);injected=true;}if(injected)++mutations;}try{if((a->pending_irqs&&!(a->ccr&128))||(at>=0x92c&&at<0x946)){check(kstation::NativeIrq::step(*b).stepped,"Timer3 native refused");++irqSteps;}else check(native.step(*b),"Native step refused");}catch(...){a->step();std::fprintf(stderr,"Failed at%x clocks%llu/%llu next%x/%x\n",at,a->cycles,b->cycles,a->getPC(),b->getPC());throw;}a->step();equal(at);++steps;}check(opened||a->getPC()==0x3ae8&&!native.active(),"Graph incomplete");for(auto r:{std::pair{0x200000,0x40000},std::pair{0xfffd00,0x300},std::pair{0xba00,0x300},std::pair{0xce00,0x400},std::pair{0xcd00,0x100},std::pair{0xc580,0x30},std::pair{0x600000,16},std::pair{0x3fff80,0x100}})check(!std::memcmp(a->memory+r.first,b->memory+r.first,r.second),"RAM/Flash/canary differs");check(x.pageWrites==y.pageWrites,"Program count differs");programs+=x.pageWrites==256;}
};}
int main(int argc,char**argv){try{if(argc<2){std::puts("SKIP private K ROM required");return 77;}std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};check(rom.size()==49728,"ROM size");Fixture f(rom);

 auto prepare=[&](unsigned mode,unsigned flags,unsigned sp=0xffff00){f.prepare(0x1838,flags,0x21fe00,sp);f.byte(0xfffe70,1);f.byte(0xbb1c,mode);f.byte(0xfffe6f,3);f.byte(0xbab0,63);f.wide(0xfffe56,0x1020304);f.wide(0xfffe66,0x12345678);f.word(0xfffe78,0x3456);f.word(0xfffe7c,0x80);f.wide(0xfffe6a,0x456789ab);f.wide(0xfffe62,0x12345678);f.word(0xc598,0xffff);};
 for(unsigned flags=0;flags<256;++flags)for(unsigned toggle:{0u,1u,0xfeu,0xffu}){prepare(flags,flags);f.byte(0xfffe70,toggle);f.whole();}
 for(unsigned mode=0;mode<256;++mode)for(unsigned flags:{0u,0x2fu,0xffu})for(unsigned seen:{0u,1u}){prepare(mode,flags);f.byte(0xfffe6f,seen);f.whole();}
 for(unsigned tempo=0;tempo<256;++tempo){prepare(1,tempo);f.byte(0xbab0,tempo);f.whole();}
 for(unsigned gain:{0u,0x80u,0x800u,0x801u,0xffffu})for(unsigned observed:{0u,0x7fffu,0x8000u,0xffffu})for(unsigned filtered:{0u,1u,0x7fffffffu,0x80000000u,0xffffffffu}){prepare(2,gain);f.word(0xfffe7c,gain);f.word(0xfffe78,observed);f.wide(0xfffe66,filtered);f.whole();}
 for(unsigned sp:{0xffff00u,0x3fffffu,0x400001u})for(unsigned mode:{0u,1u,2u}){prepare(mode,0xff,sp);f.whole();}
 for(unsigned scenario=1;scenario<9;++scenario){prepare(1,0xff);f.liveScenario=scenario;f.mutate=true;f.whole();}check(f.mutations==8,"Live clock state witnesses missing");
 uint64_t shorts=0,blocked=0;unsigned calls=0;kstation::FlashCredits cr;using T=kstation::ForegroundClockTask;for(unsigned mode:{0u,1u,2u,3u})for(unsigned gain:{0x80u,0x800u,0xffffu}){T t;while(!t.complete()){if(t.awaiting()){check(!t.nextClocks(cr),"Foreground clock child gate");++blocked;t.resume();continue;}auto advance=[&](unsigned b){return t.advanceBefore(b,cr,[&](T::Read r)->unsigned{++calls;switch(r){case T::Read::Toggle:return 1;case T::Read::Source:return mode;case T::Read::Flags:return 3;case T::Read::Tempo:return 63;case T::Read::Increment:return 0x12345678;case T::Read::Sync:return mode==2?1:0;case T::Read::Observed:return 0x4567;case T::Read::Filtered:return 0x3456789a;case T::Read::Gain:return gain;case T::Read::Ratio:return 0x456789ab;case T::Read::PreviousTempo:return 0x23456789;}return 0;},[&](auto,auto){++calls;});};shortBudgets(t,cr,calls,shorts,advance);advance(t.nextClocks(cr));}}
 std::printf("{\"passed\":true,\"closed_handlers\":%llu,\"native_phases\":%llu,\"ordered_context_io\":%llu,\"original_child_steps\":0,\"live_state_mutations\":8,\"pure_short_budgets\":%llu,\"child_gates\":%llu}\n",f.handlers,f.steps,f.io,shorts,blocked);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL:%s\n",e.what());return 1;}}
